<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart3D</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#202124;color:#ddd;font:12px Arial}.app{height:100vh;display:grid;grid-template-rows:42px 1fr 150px 24px}button,select,input{color:#ddd;background:#292b30;border:1px solid #444;border-radius:4px}button{cursor:pointer}.top{display:flex;align-items:center;gap:5px;padding:5px 8px;background:#151619;border-bottom:1px solid #3b3d42}.logo{font-size:15px;font-weight:bold;margin:0 16px 0 4px}.logo b{color:#70a8e5}.top button,.top select{height:30px;padding:0 9px}.spacer{flex:1}.main{min-height:0;display:grid;grid-template-columns:58px 1fr 250px}.toolbar{background:#1b1c20;border-right:1px solid #3b3d42;padding:7px 4px;display:flex;flex-direction:column;align-items:center;gap:6px}.tool{width:47px;height:42px;font-size:17px}.tool span{display:block;font-size:8px;color:#aaa;margin-top:3px}.tool.active{background:#3b536d;border-color:#6790b3}.viewport{position:relative;min-width:0;background:#303238}.canvas{position:absolute;inset:0}.hud{position:absolute;z-index:5;background:#111216dd;border:1px solid #484b51;border-radius:4px;padding:7px 9px;pointer-events:none;color:#aaa}.help{left:9px;top:9px}.view{right:9px;top:9px}.right{background:#202124;border-left:1px solid #3b3d42;overflow:auto}.tabs{display:flex;height:36px;border-bottom:1px solid #3b3d42}.tabs button{flex:1;border:0;background:none;border-radius:0;color:#999}.tabs .active{color:#fff;border-bottom:2px solid #70a8e5}.title{padding:10px;color:#92969d;font-size:9px;font-weight:bold;letter-spacing:1px}.outliner{padding:5px 7px;border-bottom:1px solid #383a3f}.row{height:29px;padding:7px;border-radius:4px;display:flex;align-items:center;gap:7px;cursor:pointer}.row:hover,.row.sel{background:#35383d}.type{margin-left:auto;color:#777;font-size:9px}.props{padding:10px}.group{padding:9px 0;border-bottom:1px solid #34363a}.group h4{margin:0 0 7px;color:#bbb}.trip{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.input label{display:block;color:#858990;font-size:8px;margin-bottom:3px}.input input{width:100%;height:25px;background:#141518;padding:0 5px}.addmenu{position:absolute;z-index:20;display:none;width:200px;background:#25272b;border:1px solid #4a4d52;border-radius:4px;padding:5px;box-shadow:0 10px 30px #0009}.addmenu button{display:block;width:100%;text-align:left;border:0;background:none;padding:8px}.addmenu button:hover{background:#3a3d42}.timeline{display:grid;grid-template-columns:190px 1fr;background:#191a1d;border-top:1px solid #3b3d42}.tlleft{border-right:1px solid #383a3f}.tlhead,.tlrow{height:30px;padding:8px;border-bottom:1px solid #303237}.tlhead{font-size:9px;color:#90939a;font-weight:bold}.tlmain{overflow:hidden;position:relative;background:repeating-linear-gradient(90deg,#191a1d 0,#191a1d 39px,#292c31 40px)}.frames{height:30px;display:flex;border-bottom:1px solid #303237;color:#777}.frames span{width:40px;flex:none;text-align:center;padding-top:8px;font-size:9px}.playhead{position:absolute;top:0;bottom:0;width:1px;background:#e36d75;left:12px}.footer{display:flex;justify-content:space-between;align-items:center;padding:0 9px;background:#151619;border-top:1px solid #383a3f;color:#777;font-size:9px}@media(max-width:850px){.main{grid-template-columns:52px 1fr}.right{display:none}}
</style></head><body><div class="app"><header class="top"><div class="logo">SMART<b>3D</b></div><button id="new">New</button><button id="undo">↶</button><button id="redo">↷</button><button id="save">Save</button><button id="play">▶</button><button id="frame">Frame</button><button id="enter">📷 Camera View</button><button id="exit" style="display:none">Exit Camera</button><div class="spacer"></div><select id="mode"><option>Object Mode</option><option>Edit Mode</option></select></header><div class="main"><aside class="toolbar"><button class="tool active" id="select">↖<span>Select</span></button><button class="tool" id="move">✥<span>Move</span></button><button class="tool" id="rotate">↻<span>Rotate</span></button><button class="tool" id="scale">⤢<span>Scale</span></button><div style="height:1px;width:40px;background:#3b3d42"></div><button class="tool" id="add">＋<span>Add</span></button><button class="tool" id="dup">⧉<span>Duplicate</span></button><button class="tool" id="del">×<span>Delete</span></button></aside><main class="viewport"><div id="canvas" class="canvas"></div><div class="hud help">LMB Select · G Move · R Rotate · S Scale · Shift+A Add · 0 Camera</div><div class="hud view" id="view">User Perspective</div><div id="menu" class="addmenu"><button data-a="cube">▣ Cube</button><button data-a="sphere">● UV Sphere</button><button data-a="cylinder">⬢ Cylinder</button><button data-a="cone">△ Cone</button><button data-a="plane">▱ Plane</button><button data-a="torus">◉ Torus</button><button data-a="light">☀ Point Light</button><button data-a="camera">▣ Camera</button></div></main><aside class="right"><div class="tabs"><button class="active">Scene</button><button>Properties</button></div><div class="title">Scene Collection</div><div id="outliner" class="outliner"></div><div class="props"><b>Object Properties</b><div id="props"></div></div></aside></div><div class="timeline"><div class="tlleft"><div class="tlhead">TIMELINE</div><div class="tlrow">Cube</div><div class="tlrow">Camera</div><div class="tlrow">Light</div></div><div class="tlmain"><div class="frames"><span>0</span><span>10</span><span>20</span><span>30</span><span>40</span><span>50</span><span>60</span><span>70</span><span>80</span><span>90</span><span>100</span></div><div id="playhead" class="playhead"></div></div></div><footer class="footer"><span>Smart3D</span><span id="status">Cube selected</span><span>Three.js WebGL</span></footer></div>
<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.180.0/examples/jsm/"}}</script><script type="module">
import * as THREE from 'three';import{OrbitControls}from'three/addons/controls/OrbitControls.js';import{TransformControls}from'three/addons/controls/TransformControls.js';
const host=document.getElementById('canvas'),scene=new THREE.Scene();scene.background=new THREE.Color(0x303238);const camera=new THREE.PerspectiveCamera(50,1,.05,1000);camera.position.set(7,5,8);const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.shadowMap.enabled=true;host.appendChild(renderer.domElement);const orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.target.set(0,1,0);const gizmo=new TransformControls(camera,renderer.domElement);scene.add(gizmo.getHelper());gizmo.addEventListener('dragging-changed',e=>orbit.enabled=!e.value);scene.add(new THREE.GridHelper(30,30,0x666a72,0x45484e));scene.add(new THREE.AxesHelper(3));scene.add(new THREE.HemisphereLight(0xffffff,0x343434,1.2));
const objects=[];let selected=null,mode='select',playing=false,inside=false,oldPos=null,oldQuat=null;
function helperLight(l){const h=new THREE.PointLightHelper(l,.45,0xffcc66);h.material.depthTest=false;h.renderOrder=10;scene.add(h);l.userData.helper=h}function helperCamera(c){const h=new THREE.CameraHelper(c);h.material.depthTest=false;h.renderOrder=10;scene.add(h);c.userData.helper=h}function unique(n){let x=n,i=1;while(objects.some(o=>o.name===x))x=n+'.'+String(++i).padStart(3,'0');return x}function mesh(n,g){const m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:0x8b8e94,roughness:.62}));m.name=n;m.castShadow=true;m.receiveShadow=true;return m}
function add(kind){let o;if(kind==='cube'){o=mesh('Cube',new THREE.BoxGeometry(2,2,2));o.position.y=1}else if(kind==='sphere'){o=mesh('Sphere',new THREE.SphereGeometry(1,32,20));o.position.y=1}else if(kind==='cylinder'){o=mesh('Cylinder',new THREE.CylinderGeometry(1,1,2,32));o.position.y=1}else if(kind==='cone'){o=mesh('Cone',new THREE.ConeGeometry(1,2,32));o.position.y=1}else if(kind==='plane'){o=mesh('Plane',new THREE.PlaneGeometry(4,4));o.rotation.x=-Math.PI/2}else if(kind==='torus'){o=mesh('Torus',new THREE.TorusGeometry(1,.3,20,64));o.position.y=1}else if(kind==='light'){o=new THREE.PointLight(0xffffff,80,35);o.name='Light';o.position.set(4,5,3);helperLight(o)}else if(kind==='camera'){o=new THREE.PerspectiveCamera(50,1,.1,1000);o.name='Camera';o.position.set(6,4,6);o.lookAt(0,1,0);helperCamera(o)}else return;o.name=unique(o.name);scene.add(o);objects.push(o);select(o);ui()}
function select(o){selected=o||null;gizmo.detach();if(selected?.isMesh&&mode!=='select'){gizmo.setMode(mode);gizmo.attach(selected)}document.getElementById('status').textContent=selected?selected.name+' selected':'Nothing selected';ui()}function ui(){const out=document.getElementById('outliner');out.innerHTML=objects.map((o,i)=>`<div class="row ${o===selected?'sel':''}" data-i="${i}">◈ ${o.name}<span class="type">${o.type}</span></div>`).join('');out.querySelectorAll('.row').forEach(r=>r.onclick=()=>select(objects[+r.dataset.i]));if(!selected){document.getElementById('props').innerHTML='';return}document.getElementById('props').innerHTML='<div class="group"><h4>Transform</h4><div class="trip">'+['x','y','z'].map(a=>`<div class="input"><label>POSITION ${a.toUpperCase()}</label><input data-p="${a}" value="${selected.position[a].toFixed(2)}"></div>`).join('')+'</div><div class="trip" style="margin-top:8px">'+['x','y','z'].map(a=>`<div class="input"><label>ROTATION ${a.toUpperCase()}</label><input data-r="${a}" value="${THREE.MathUtils.radToDeg(selected.rotation[a]).toFixed(1)}"></div>`).join('')+'</div><div class="trip" style="margin-top:8px">'+['x','y','z'].map(a=>`<div class="input"><label>SCALE ${a.toUpperCase()}</label><input data-s="${a}" value="${selected.scale[a].toFixed(2)}"></div>`).join('')+'</div></div>';document.querySelectorAll('[data-p]').forEach(i=>i.oninput=()=>selected.position[i.dataset.p]=+i.value);document.querySelectorAll('[data-r]').forEach(i=>i.oninput=()=>selected.rotation[i.dataset.r]=THREE.MathUtils.degToRad(+i.value));document.querySelectorAll('[data-s]').forEach(i=>i.oninput=()=>selected.scale[i.dataset.s]=+i.value)}
function reset(){for(const o of [...objects]){if(o.userData.helper)scene.remove(o.userData.helper);scene.remove(o)}objects.length=0;const c=addBase('cube');const l=addBase('light');l.position.set(4,5,3);const cam=addBase('camera');cam.position.set(7,5,8);cam.lookAt(0,1,0);select(c)}function addBase(k){let o;if(k==='cube'){o=mesh('Cube',new THREE.BoxGeometry(2,2,2));o.position.y=1}else if(k==='light'){o=new THREE.PointLight(0xffffff,80,35);o.name='Light';o.position.set(4,5,3);helperLight(o)}else{o=new THREE.PerspectiveCamera(50,1,.1,1000);o.name='Camera';o.position.set(7,5,8);o.lookAt(0,1,0);helperCamera(o)}scene.add(o);objects.push(o);return o}
function enterCamera(){const c=objects.find(o=>o.isCamera);if(!c)return;oldPos=camera.position.clone();oldQuat=camera.quaternion.clone();camera.position.copy(c.position);camera.quaternion.copy(c.quaternion);camera.fov=c.fov;camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();orbit.enabled=false;inside=true;document.getElementById('enter').style.display='none';document.getElementById('exit').style.display='inline-block';document.getElementById('view').textContent='CAMERA VIEW';document.getElementById('status').textContent='Inside Camera'}function exitCamera(){if(!inside)return;camera.position.copy(oldPos);camera.quaternion.copy(oldQuat);camera.updateProjectionMatrix();orbit.enabled=true;inside=false;document.getElementById('enter').style.display='inline-block';document.getElementById('exit').style.display='none';document.getElementById('view').textContent='User Perspective';document.getElementById('status').textContent='User Perspective'}
const menu=document.getElementById('menu');document.getElementById('add').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();menu.style.left=(r.right+6)+'px';menu.style.top=r.top+'px';menu.style.display=menu.style.display==='block'?'none':'block'};document.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{add(b.dataset.a);menu.style.display='none'});document.addEventListener('click',e=>{if(e.target.id!=='add'&&!e.target.closest('#menu'))menu.style.display='none'});document.getElementById('del').onclick=()=>{if(!selected)return;if(selected.userData.helper)scene.remove(selected.userData.helper);scene.remove(selected);objects.splice(objects.indexOf(selected),1);select(objects[0]||null)};document.getElementById('dup').onclick=()=>{if(!selected?.isMesh)return;const o=mesh(unique(selected.name),selected.geometry.clone());o.material=selected.material.clone();o.position.copy(selected.position).add(new THREE.Vector3(1,0,1));o.rotation.copy(selected.rotation);o.scale.copy(selected.scale);scene.add(o);objects.push(o);select(o)};document.getElementById('new').onclick=reset;document.getElementById('enter').onclick=enterCamera;document.getElementById('exit').onclick=exitCamera;document.getElementById('frame').onclick=()=>{if(!selected)return;orbit.target.copy(selected.position);camera.position.copy(selected.position).add(new THREE.Vector3(6,4,7))};document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'⏸':'▶'};
for(const [id,m] of [['select','select'],['move','translate'],['rotate','rotate'],['scale','scale']])document.getElementById(id).onclick=()=>{mode=m;document.querySelectorAll('.tool').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');if(selected?.isMesh&&m!=='select'){gizmo.setMode(m);gizmo.attach(selected)}else gizmo.detach()};
const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0||inside||gizmo.dragging)return;const r=renderer.domElement.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width*2-1;mouse.y=-(e.clientY-r.top)/r.height*2+1;ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects(objects.filter(o=>o.isMesh),false);select(hit.length?hit[0].object:null)});window.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;const k=e.key.toLowerCase();if(k==='g')document.getElementById('move').click();else if(k==='r')document.getElementById('rotate').click();else if(k==='s')document.getElementById('scale').click();else if(k==='delete')document.getElementById('del').click();else if(k==='d'&&e.ctrlKey)document.getElementById('dup').click();else if(e.shiftKey&&k==='a')document.getElementById('add').click();else if(k==='0')inside?exitCamera():enterCamera();else if(k==='escape'){menu.style.display='none';if(inside)exitCamera();document.getElementById('select').click()}});
function resize(){const r=host.getBoundingClientRect();camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height);objects.filter(o=>o.isCamera).forEach(c=>{c.aspect=r.width/r.height;c.updateProjectionMatrix();c.userData.helper?.update()})}new ResizeObserver(resize).observe(host);reset();resize();let t=0;(function loop(){requestAnimationFrame(loop);if(playing){t=(t+.5)%100;document.getElementById('playhead').style.left=(12+t*4)+'px'}objects.forEach(o=>o.userData.helper?.update());orbit.update();renderer.render(scene,camera)})();
</script></body></html>